// Normalizar falla no prevista (Error Trigger): toma solo campos permitidos.
// El texto del error se usa únicamente para detectar palabras clave de un vocabulario fijo; nunca se copia.
const j = $input.first().json || {};
const ex = (j.execution && typeof j.execution === 'object') ? j.execution : {};
const tr = (j.trigger && typeof j.trigger === 'object') ? j.trigger : {};
const wf = (j.workflow && typeof j.workflow === 'object') ? j.workflow : {};
const err = (ex.error && typeof ex.error === 'object') ? ex.error : ((tr.error && typeof tr.error === 'object') ? tr.error : {});
const texto = [err.message, err.description, err.name].filter(x => typeof x === 'string').join(' ').slice(0, 2000);
const VOCABULARIO = [
  ['falla_sintetica', /FALLA_SINTETICA_R1/],
  ['credencial', /\b(401|403)\b|unauthori[sz]ed|forbidden|credential|invalid_grant|permission/i],
  ['cuota', /\b429\b|rate limit|quota|too many requests/i],
  ['tiempo', /timeout|timed out|ETIMEDOUT|ECONNABORTED/i],
  ['conexion', /ECONNRESET|ENOTFOUND|ECONNREFUSED|socket hang up|network/i],
  ['servicio', /\b5\d\d\b|service unavailable|bad gateway|not able to process/i],
  ['codigo', /ReferenceError|TypeError|SyntaxError|is not defined|cannot read/i],
  ['no_encontrado', /\b404\b|not found|does not exist/i],
];
const pistas = VOCABULARIO.filter(([, re]) => re.test(texto)).map(([k]) => k);
const nodoTrigger = (tr.error && tr.error.node && typeof tr.error.node.name === 'string') ? tr.error.node.name : '';
return [{ json: {
  entrada: 'ERROR_TRIGGER', codigos: ['FALLA_NO_PREVISTA'], pistas,
  workflow_id: String(wf.id ?? ''), workflow_nombre: String(wf.name ?? ''),
  ejecucion_id: String(ex.id ?? ''), nodo: String(ex.lastNodeExecuted ?? nodoTrigger ?? ''),
  falla_en_disparador: !ex.id && !!j.trigger, id_consulta: '', canal: '', codigo_error: '',
} }];

// Clasificar y validar incidente: circuito único para ambas entradas. Solo campos permitidos y categorías fijas.
const n = $input.first().json || {};
const CODIGOS = ['FALLA_NO_PREVISTA', 'INTEGRACION_WF03', 'ERR_SHEETS', 'ERROR_PROCESAMIENTO', 'REGISTRO_NO_CONFIRMADO', 'AVISO_ERROR_ENVIO', 'AVISO_VERIFICACION_MANUAL'];
const CAT_CODIGO = { INTEGRACION_WF03: 'INTEGRACION', ERR_SHEETS: 'REGISTRO_SHEETS', ERROR_PROCESAMIENTO: 'PROCESAMIENTO', REGISTRO_NO_CONFIRMADO: 'REGISTRO_SHEETS', AVISO_ERROR_ENVIO: 'AVISO_GMAIL', AVISO_VERIFICACION_MANUAL: 'AVISO_GMAIL' };
const CAT_PISTA = { falla_sintetica: 'PRUEBA_SINTETICA', credencial: 'CREDENCIAL_O_PERMISOS', cuota: 'CUOTA_O_LIMITE', tiempo: 'TIEMPO_DE_ESPERA', conexion: 'CONEXION', servicio: 'SERVICIO_EXTERNO', codigo: 'ERROR_DE_CODIGO', no_encontrado: 'RECURSO_NO_ENCONTRADO' };
const ok = (v, re) => (typeof v === 'string' && re.test(v)) ? v : '';
const codigos = Array.isArray(n.codigos) ? n.codigos.filter(c => CODIGOS.includes(c)) : [];
if (!codigos.length) return [{ json: { es_incidente: false, motivo: n.error ? 'ERROR_EN_NORMALIZACION' : 'SIN_INCIDENTE' } }];
const pistas = Array.isArray(n.pistas) ? n.pistas.filter(p => CAT_PISTA[p]) : [];
const codigo = codigos[0];
const categoria = codigo === 'FALLA_NO_PREVISTA' ? (pistas.length ? CAT_PISTA[pistas[0]] : 'OTRA') : CAT_CODIGO[codigo];
const severidad = ['FALLA_NO_PREVISTA', 'INTEGRACION_WF03', 'ERR_SHEETS', 'ERROR_PROCESAMIENTO', 'REGISTRO_NO_CONFIRMADO'].includes(codigo) ? 'Alta' : 'Media';
const inc = {
  es_incidente: true, entrada: n.entrada === 'ERROR_TRIGGER' ? 'ERROR_TRIGGER' : 'INCIDENTE_CONTROLADO',
  codigo, codigos, categoria, severidad,
  workflow_id: ok(n.workflow_id, /^[A-Za-z0-9]{8,32}$/),
  workflow_nombre: ok(n.workflow_nombre, /^[\p{L}\p{N} ._()-]{1,80}$/u) || 'Workflow no identificado',
  ejecucion_id: ok(n.ejecucion_id, /^\d{1,12}$/),
  nodo: ok(n.nodo, /^[\p{L}\p{N} ._()-]{1,80}$/u),
  falla_en_disparador: n.falla_en_disparador === true,
  id_consulta: ok(n.id_consulta, /^CON-[A-Za-z0-9-]{1,60}$/),
  canal: ['CHAT', 'WEBHOOK'].includes(n.canal) ? n.canal : '',
  codigo_error: ok(n.codigo_error, /^ERR_[A-Z_]{3,30}$/),
  fecha_hora: $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd HH:mm'),
};
// Clave del incidente: identifica la ejecución o la consulta afectada y los códigos detectados.
const ref = inc.ejecucion_id ? (inc.workflow_id || inc.workflow_nombre) + ':' + inc.ejecucion_id : (inc.id_consulta || 'sin-referencia:' + inc.fecha_hora);
inc.clave = inc.entrada + '|' + ref + '|' + codigos.join(',');
return [{ json: inc }];

// Normalizar incidente controlado (llamado desde WF-02): valida los campos recibidos y vuelve a aplicar las reglas.
// Los casos normales (bloqueos de privacidad, legajos inválidos, rechazos, Gmail deshabilitado) no generan incidente.
function codigosIncidente(d) {
  const c = [];
  if (d.resultado_validacion === 'RECHAZADA') return c;
  if (d.resultado_validacion === 'ERROR_INTERNO') return ['ERROR_PROCESAMIENTO'];
  if (d.registro === 'DESCONOCIDO') c.push('INTEGRACION_WF03');
  if (d.codigo_error === 'ERR_SHEETS') c.push('ERR_SHEETS');
  else if (d.estado_procesamiento === 'ERROR' && !c.includes('INTEGRACION_WF03')) c.push('ERROR_PROCESAMIENTO');
  if (d.registro === 'NO_REGISTRADA' && !c.includes('ERR_SHEETS')) c.push('REGISTRO_NO_CONFIRMADO');
  if (d.aviso_estado === 'ERROR_ENVIO') c.push('AVISO_ERROR_ENVIO');
  if (d.aviso_estado === 'VERIFICACION_MANUAL' || d.aviso_verificacion === true) c.push('AVISO_VERIFICACION_MANUAL');
  return c;
}
const j = $input.first().json || {};
const s = v => (typeof v === 'string' ? v.trim() : '');
const de = (v, lista) => lista.includes(s(v)) ? s(v) : '';
const d = {
  resultado_validacion: de(j.resultado_validacion, ['VALIDA', 'BLOQUEADA_SALUD', 'RECHAZADA', 'ERROR_INTERNO']),
  estado_procesamiento: de(j.estado_procesamiento, ['COMPLETADO', 'BLOQUEADO', 'ERROR', 'RECHAZADA']),
  codigo_error: de(j.codigo_error, ['ERR_LLM_NO_DISPONIBLE', 'ERR_LLM_TIMEOUT', 'ERR_LLM_SALIDA_INVALIDA', 'ERR_VECTOR_STORE', 'ERR_SHEETS']),
  registro: de(j.registro, ['REGISTRADA', 'YA_REGISTRADA', 'NO_REGISTRADA', 'DESCONOCIDO']),
  aviso_estado: de(j.aviso_estado, ['NO_CORRESPONDE', 'NO_ENVIADO', 'PENDIENTE_DE_ENVIO', 'ENVIADO', 'ERROR_ENVIO', 'VERIFICACION_MANUAL']),
  aviso_verificacion: j.aviso_verificacion === true,
};
return [{ json: {
  entrada: 'INCIDENTE_CONTROLADO', codigos: codigosIncidente(d), pistas: [],
  workflow_id: s(j.workflow_origen) === 'WF-02' ? 'REEMPLAZARIDWF02' : '', workflow_nombre: s(j.workflow_origen) === 'WF-02' ? 'WF-02 Recepción' : '',
  ejecucion_id: s(j.ejecucion_id), nodo: '', falla_en_disparador: false,
  id_consulta: s(j.id_consulta), canal: de(j.canal, ['CHAT', 'WEBHOOK']), codigo_error: d.codigo_error,
} }];

// Evitar duplicados: guarda las claves notificadas en los datos estáticos del workflow (24 h, máximo 200).
// Solo contiene claves técnicas (workflow, ejecución, consulta y códigos), sin datos personales.
// n8n persiste estos datos solo en ejecuciones de producción; en pruebas manuales no se conservan.
const i = $input.first().json || {};
let duplicado = false;
try {
  const st = $getWorkflowStaticData('global');
  const ahora = Date.now(), TTL = 24 * 3600 * 1000;
  st.incidentes = (Array.isArray(st.incidentes) ? st.incidentes : []).filter(x => x && ahora - x.t < TTL).slice(-199);
  duplicado = st.incidentes.some(x => x.k === i.clave);
  if (!duplicado) st.incidentes.push({ k: i.clave, t: ahora });
} catch (e) { duplicado = false; }
return [{ json: { ...i, duplicado } }];

// Configuración de la alerta. Envío deshabilitado. Solo se envía a una casilla de la lista autorizada.
// Antes de exportar el workflow, dejar estos valores vacíos.
const ALERTA_DESTINATARIOS_AUTORIZADOS = [];
const ALERTA_DESTINATARIO = '';
const ALERTA_ENVIO_HABILITADO = false;
return [{ json: { ...$input.first().json, alerta_destinatario: ALERTA_DESTINATARIO, alerta_destinatarios_autorizados: ALERTA_DESTINATARIOS_AUTORIZADOS, alerta_envio_habilitado: ALERTA_ENVIO_HABILITADO } }];

// Preparar alerta: arma el correo solo con campos permitidos y lo valida antes de habilitar el envío.
const i = $input.first().json || {};
const DESC = {
  FALLA_NO_PREVISTA: 'Falla no prevista: la ejecución terminó con error.',
  INTEGRACION_WF03: 'WF-02 no obtuvo una respuesta válida de WF-03.',
  ERR_SHEETS: 'Falla de Google Sheets: la consulta pudo no quedar registrada.',
  ERROR_PROCESAMIENTO: 'La consulta terminó con estado ERROR.',
  REGISTRO_NO_CONFIRMADO: 'No se confirmó el registro de la consulta en Consultas.',
  AVISO_ERROR_ENVIO: 'Gmail rechazó el aviso de una derivación.',
  AVISO_VERIFICACION_MANUAL: 'El resultado del aviso de derivación requiere verificación manual.',
};
const asunto = '[PRUEBA ACADÉMICA] [ALERTA] ' + (i.severidad === 'Alta' ? '[ALTA] ' : '') + i.codigo + ' en ' + i.workflow_nombre;
const cuerpo = [
  'Alerta de monitoreo (prototipo académico, datos ficticios).', '',
  'Incidente: ' + (DESC[i.codigo] || i.codigo),
  'Códigos detectados: ' + (i.codigos || []).join(', '),
  'Categoría: ' + i.categoria,
  'Severidad: ' + i.severidad,
  'Workflow: ' + i.workflow_nombre,
  'Ejecución: ' + (i.ejecucion_id || 'no disponible'),
  'Nodo: ' + (i.nodo || 'no disponible') + (i.falla_en_disparador ? ' (falla en el disparador)' : ''),
  'Consulta: ' + (i.id_consulta || 'no disponible'),
  'Canal: ' + (i.canal || 'no disponible'),
  'Código de error registrado: ' + (i.codigo_error || 'ninguno'),
  'Fecha y hora: ' + i.fecha_hora, '',
  'Revisá la ejecución en n8n. Este aviso no incluye mensajes, legajos, encabezados ni detalles técnicos del error.',
].join('\n');
const salida = (alerta, enviar, correo) => [{ json: { ...i, alerta, enviar, correo: correo || null } }];
// Control de contenido previo al envío
const prohibido = /@|LEG-\d{4}|\d{13,}|token|password|contrase[ñn]a|bearer|authorization|x-cordal|stack|at \S+\.js/i;
if (prohibido.test(asunto + '\n' + cuerpo)) return salida({ estado: 'NO_ENVIADA', motivo: 'CONTENIDO_NO_PERMITIDO' }, false, { asunto, cuerpo });
const dest = String(i.alerta_destinatario || '').trim().toLowerCase();
const aut = Array.isArray(i.alerta_destinatarios_autorizados) ? i.alerta_destinatarios_autorizados.map(x => String(x).trim().toLowerCase()) : [];
if (!dest || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(dest) || /@cordal\.example$/.test(dest) || !aut.includes(dest)) return salida({ estado: 'NO_ENVIADA', motivo: 'SIN_DESTINATARIO_AUTORIZADO' }, false, { asunto, cuerpo });
if (i.alerta_envio_habilitado !== true) return salida({ estado: 'NO_ENVIADA', motivo: 'ENVIO_DESHABILITADO' }, false, { asunto, cuerpo });
return salida({ estado: 'PENDIENTE_DE_ENVIO', motivo: '' }, true, { para: dest, asunto, cuerpo });

// Resultado del monitoreo: resumen final con campos técnicos permitidos, para cualquier ruta.
let cl = {}, inc = null, prep = null;
try { cl = $('Clasificar y validar incidente').first().json || {}; } catch (e) { cl = {}; }
try { if ($('Evitar duplicados').isExecuted) inc = $('Evitar duplicados').first().json; } catch (e) { inc = null; }
try { if ($('Preparar alerta').isExecuted) prep = $('Preparar alerta').first().json; } catch (e) { prep = null; }
const r = $input.first().json || {};
let alerta;
if (!cl.es_incidente) alerta = { estado: 'NO_CORRESPONDE', motivo: cl.motivo || 'SIN_INCIDENTE' };
else if (inc && inc.duplicado) alerta = { estado: 'DUPLICADA', motivo: 'INCIDENTE_YA_NOTIFICADO' };
else if (!prep) alerta = { estado: 'ERROR', motivo: 'ALERTA_NO_PREPARADA' };
else if (!prep.enviar) alerta = prep.alerta;
else {
  const id = (!r.error && typeof r.id === 'string') ? r.id : '';
  const txt = r.error ? JSON.stringify(r.error) : '';
  if (id) alerta = { estado: 'ENVIADA', motivo: '', id_mensaje: id };
  else if (r.error && /\b(400|401|403|404|429)\b|bad request|unauthori|forbidden|invalid_grant|quota|rate limit/i.test(txt) && !/timeout|ECONNRESET|socket hang up|\b5\d\d\b/i.test(txt)) alerta = { estado: 'ERROR', motivo: 'ERROR_GMAIL' };
  else alerta = { estado: 'VERIFICACION_MANUAL', motivo: r.error ? 'RESULTADO_INCIERTO_GMAIL' : 'SIN_CONFIRMACION_DE_GMAIL' };
}
return [{ json: { clave: cl.clave || '', entrada: cl.entrada || '', codigo: cl.codigo || '', categoria: cl.categoria || '', severidad: cl.severidad || '',
  workflow: cl.workflow_nombre || '', ejecucion_id: cl.ejecucion_id || '', id_consulta: cl.id_consulta || '', alerta } }];
